package api

var sswCurriculumWoodIndustryScenariosEnglish = map[examSSWEnglishKey]string{
	{field: "ssw.scenario", source: `Satu tumpukan papan tidak memiliki label, tetapi pekerja diminta memindahkannya ke area bahan produksi.`}:                           `A stack of boards has no label, but a worker is asked to move it to the production-material area.`,
	{field: "ssw.scenario", source: `Papan yang akan diproses memiliki retak panjang di ujung, tetapi dokumen tidak menjelaskan apakah retak itu dapat diterima.`}:       `A board to be processed has a long crack at one end, but the documents do not say whether it is acceptable.`,
	{field: "ssw.scenario", source: `Alat ukur menunjukkan hasil yang berbeda jauh dari kartu target pada satu tumpukan papan.`}:                                         `A measuring tool gives a result far from the target on the card for a stack of boards.`,
	{field: "ssw.scenario", source: `Pelindung konveyor tidak menutup penuh, tetapi operator berikutnya sudah menyiapkan kayu untuk masuk.`}:                             `A conveyor guard does not close fully, but the next operator has already prepared wood to feed into it.`,
	{field: "ssw.scenario", source: `Lembar kerja menunjukkan ketebalan berbeda dari label pada tumpukan, dan pemotongan belum dimulai.`}:                                `The work sheet gives a thickness that differs from the stack label, and cutting has not started.`,
	{field: "ssw.scenario", source: `Satu lembar venir memiliki tanda arah berbeda dari lembar lain dalam kelompok panel.`}:                                              `One veneer sheet has a direction marking that differs from the other sheets in the panel lot.`,
	{field: "ssw.scenario", source: `Sampel pertama menunjukkan ketebalan di luar toleransi yang tercantum pada lembar kerja.`}:                                          `The first sample has a thickness outside the tolerance listed on the work sheet.`,
	{field: "ssw.scenario", source: `Beberapa papan memiliki serpihan tajam di tepi setelah proses planing, tetapi pekerja belum tahu apakah boleh dihaluskan sendiri.`}: `Several boards have sharp splinters along the edge after planing, and the worker does not know whether they may smooth them independently.`,
	{field: "ssw.scenario", source: `Label grade pada satu bundel basah dan tulisannya tidak dapat dibaca sebelum masuk ke area pengiriman.`}:                            `The grade label on a bundle is wet and illegible before the bundle enters the dispatch area.`,
	{field: "ssw.scenario", source: `Tumpukan papan mulai miring setelah satu penyangga bergeser, sementara pekerja hendak menaruh papan baru di atasnya.`}:              `A stack of boards starts leaning after one support shifts, while a worker is about to place another board on top.`,
	{field: "ssw.scenario", source: `Satu bundel memiliki ukuran benar, tetapi labelnya menunjukkan pelanggan berbeda dari daftar muat.`}:                                `A bundle has the correct dimensions, but its label shows a different customer from the loading list.`,
	{field: "ssw.scenario", source: `Pada akhir giliran, pekerja melihat kebocoran kecil dekat mesin dan belum tahu apakah lini harus dihentikan.`}:                      `At the end of the shift, a worker notices a small leak near a machine and is unsure whether the line must be stopped.`,
}

var sswCurriculumWoodIndustryResponsesEnglish = map[examSSWEnglishKey]string{
	{field: "ssw.response", source: `Pisahkan tumpukan, catat lokasinya, dan minta penanggung jawab menelusuri identitas sebelum pemindahan.`}:                                 `Separate the stack, record its location, and ask the person in charge to trace its identity before it is moved.`,
	{field: "ssw.response", source: `Pisahkan papan dan minta petugas mutu memeriksa sesuai kriteria sebelum diproses.`}:                                                       `Set the board aside and ask quality-control staff to check it against the criteria before processing.`,
	{field: "ssw.response", source: `Ulangi pemeriksaan hanya sesuai instruksi, catat pembacaan, dan tahan pemindahan sampai penanggung jawab menilai hasilnya.`}:              `Repeat the check only as instructed, record the reading, and hold the transfer until the person in charge evaluates the result.`,
	{field: "ssw.response", source: `Tunda pengumpanan, jauhkan orang dari titik bahaya, dan laporkan pelindung agar diperiksa sebelum mesin dipakai.`}:                        `Hold the feed, keep people away from the hazard, and report the guard for inspection before using the machine.`,
	{field: "ssw.response", source: `Jangan memasukkan bahan. Tahan setelan, cocokkan kedua dokumen, dan minta penanggung jawab memastikan instruksi yang berlaku.`}:           `Do not feed the material. Keep the settings unchanged, compare both documents, and ask the person in charge to confirm the applicable instruction.`,
	{field: "ssw.response", source: `Hentikan penyusunan lapisan dan pisahkan lembar tersebut; minta operator atau pemimpin memastikan orientasi sebelum proses berlanjut.`}:   `Stop arranging the layers and set the sheet aside; ask the operator or lead to confirm its orientation before continuing.`,
	{field: "ssw.response", source: `Tahan produk sejak pemeriksaan terakhir, catat hasil sebenarnya, dan panggil petugas mutu atau pemimpin lini.`}:                           `Hold products made since the last inspection, record the actual result, and call quality-control staff or the line lead.`,
	{field: "ssw.response", source: `Pisahkan papan dan minta petugas mutu menentukan perbaikan atau penolakan sesuai prosedur.`}:                                              `Set the boards aside and ask quality-control staff to determine repair or rejection under procedure.`,
	{field: "ssw.response", source: `Tahan bundel di area pemeriksaan, catat nomor lot yang masih terlihat, dan minta petugas mutu memulihkan identitasnya.`}:                  `Hold the bundle in the inspection area, record any visible lot number, and ask quality-control staff to restore its identity.`,
	{field: "ssw.response", source: `Hentikan penambahan, jauhkan orang dari arah roboh, dan minta operator atau pemimpin menstabilkan tumpukan dengan prosedur yang sesuai.`}: `Stop adding boards, keep people clear of the fall path, and ask the operator or lead to stabilize the stack using the proper procedure.`,
	{field: "ssw.response", source: `Tahan bundel dan cocokkan nomor lot dengan pesanan serta catatan produksi sebelum pemuatan.`}:                                             `Hold the bundle and match its lot number to the order and production records before loading.`,
	{field: "ssw.response", source: `Jaga jarak dari area berisiko, ikuti prosedur penghentian atau tanda fasilitas, dan segera beri tahu pemimpin sebelum serah terima.`}:     `Keep clear of the risk area, follow the shutdown procedure or facility signage, and notify the lead promptly before handover.`,
}
